/* Buffered console output (ruling 90). The buffer lives in the runtime rather than
 * in the library so that the flush has a home the generator can call; the library
 * formats and calls `extc_cout_put`, which the C compiler inlines into it (same
 * translation unit, small body). */
static uint8_t extc_cout_buf[1 << 18];
static int64_t extc_cout_len = 0;
void extc_cout_flush(void);
void extc_cout_put(uint8_t *p, int64_t n);
