void extc_cout_flush(void) {
    if (extc_cout_len <= 0) return;
    /* Through stdio: `unistd.h` cannot be included here (the library declares
     * `read`/`write` with its own prototypes, and the two clash). stdio also keeps
     * the order with the deprecated print path and flushes at exit by itself. */
    fwrite(extc_cout_buf, 1, (size_t)extc_cout_len, stdout);
    /* `fwrite` alone only fills stdio's own buffer, which stays invisible while stdout is
     * a file or a pipe (fully buffered) until the process exits: a program that prints,
     * calls `io::flushCout` and then keeps running would show nothing to a reader. */
    fflush(stdout);
    extc_cout_len = 0;
}
void extc_cout_put(uint8_t *p, int64_t n) {
    if (n <= 0) return;
    /* A single write **larger than the whole buffer** goes straight out, after the buffer
     * is drained so the order is kept. Without this the memcpy below runs past the end of
     * `extc_cout_buf`: `io::cout << <300 KB slice>` aborts with glibc's
     * "buffer overflow detected" (ASan reports a global-buffer-overflow WRITE of the
     * whole length). Flushing only when the buffer is *nearly* full does nothing for a
     * write bigger than the buffer itself; this branch takes a single write of a whole
     * buffer (256 KiB) or more. */
    if (n >= (int64_t)sizeof extc_cout_buf) {
        extc_cout_flush();
        fwrite(p, 1, (size_t)n, stdout);
        fflush(stdout);
        return;
    }
    if (extc_cout_len + n > (int64_t)sizeof extc_cout_buf) extc_cout_flush();
    memcpy(extc_cout_buf + extc_cout_len, p, (size_t)n);
    extc_cout_len += n;
}
void extc_printf(const char *fmt, ...) {
    char b[256];
    va_list ap;
    int n;
    va_start(ap, fmt);
    n = vsnprintf(b, sizeof b, fmt, ap);
    va_end(ap);
    if (n <= 0) return;
    if ((size_t)n > sizeof b - 1) n = (int)(sizeof b - 1);
    extc_cout_put((uint8_t *)b, (int64_t)n);
}
/* Generic recursive printer. The output format must stay byte-for-byte identical to
 * the `_debug` helpers it replaces; the truth table lives in
 * tools/print-formats.txt (floats use %g, [N]u8 prints numerically, and
 * slice<u8> prints as text). */
static void extc_print(const void *p, const ExtcDesc *d) {
    switch (d->kind) {
    case EXTC_D_I8:   extc_printf("%d", (int)*(const int8_t *)p); return;
    case EXTC_D_I16:  extc_printf("%d", (int)*(const int16_t *)p); return;
    case EXTC_D_I32:  extc_printf("%d", (int)*(const int32_t *)p); return;
    case EXTC_D_I64:  extc_printf("%lld", (long long)*(const int64_t *)p); return;
    case EXTC_D_U8:   extc_printf("%u", (unsigned)*(const uint8_t *)p); return;
    case EXTC_D_U16:  extc_printf("%u", (unsigned)*(const uint16_t *)p); return;
    case EXTC_D_U32:  extc_printf("%u", (unsigned)*(const uint32_t *)p); return;
    case EXTC_D_U64:  extc_printf("%llu", (unsigned long long)*(const uint64_t *)p); return;
    case EXTC_D_F32:  extc_printf("%g", (double)*(const float *)p); return;
    case EXTC_D_F64:  extc_printf("%g", (double)*(const double *)p); return;
    case EXTC_D_BOOL: extc_printf("%s", *(const bool *)p ? "true" : "false"); return;
    case EXTC_D_REF:  extc_printf("<ref>"); return;
    case EXTC_D_TEXT: {
        int64_t n = *(const int64_t *)((const char *)p + sizeof(void *));
        extc_printf("%.*s", (int)n, (const char *)*(const void *const *)p);
        return;
    }
    case EXTC_D_ENUM: {
        const char *const *names = (const char *const *)d->table;
        int tag = *(const int *)p;
        if (tag < 0 || (size_t)tag >= d->count) extc_printf("<%s>", d->name);
        else                                    extc_printf("%s", names[tag]);
        return;
    }
    case EXTC_D_STRUCT: {
        const ExtcField *f = (const ExtcField *)d->table;
        extc_printf("%s { ", d->name);
        for (size_t i = 0; i < d->count; i++) {
            if (i) extc_printf(", ");
            extc_printf("%s: ", f[i].name);
            extc_print((const char *)p + f[i].off, f[i].desc);
        }
        extc_printf(" }");
        return;
    }
    case EXTC_D_ARRAY:
    case EXTC_D_SLICE: {
        const char *data;
        size_t n;
        if (d->kind == EXTC_D_SLICE) {
            const int64_t len = *(const int64_t *)((const char *)p + sizeof(void *));
            data = (const char *)*(const void *const *)p;
            n = len > 0 ? (size_t)len : 0;
        } else {
            data = (const char *)p;
            n = d->count;
        }
        extc_printf("[");
        for (size_t i = 0; i < n; i++) {
            if (i) extc_printf(", ");
            extc_print(data + i * d->size, d->elem);
        }
        extc_printf("]");
        return;
    }
    }
}

